"""Build public documentation from the supported profile catalog and real captures."""
from pathlib import Path
import json,html,shutil
R=Path(__file__).resolve().parents[1];D=R/'docs';P=D/'screenshots';P.mkdir(parents=True,exist_ok=True)
URL='https://roxas2712.github.io/uni-language-ascendant/'
REPO='https://github.com/Roxas2712/uni-language-ascendant';RELEASE=REPO+'/releases/latest'
rows=json.loads((R/'tools/rom_requirements.json').read_text())
names={'en':'English','de':'Deutsch','pt-BR':'Português brasileiro','es':'Español','fr':'Français','it':'Italiano','ja':'日本語','ko':'한국어'}
games={'red':'Red','blue':'Blue','yellow':'Yellow','gold':'Gold','silver':'Silver','crystal':'Crystal','firered':'FireRed','leafgreen':'LeafGreen','ruby':'Ruby','sapphire':'Sapphire','emerald':'Emerald'}
shots=[('language-menu.png','build/live-switch/red-language-menu.png','In-game language menu','The new Ascendant language screen, captured in the running game.'),('language-choices.png','build/live-switch/red-language-choices.png','Available and missing languages','Game languages for Red. Imported profiles can be selected; unsupported profiles remain greyed out.'),('red-german.png','build/live-switch/red-nurse-de.png','Red: German after an in-game switch','Actual nurse dialogue after changing language in the same running application, shown with the standard renderer.'),('crystal-japanese.png','build/asian-gen2/live/crystal-ja-nurse-healed.png','Japanese Crystal: actual nurse dialogue','The original nurse interaction in Japanese Crystal’s language profile.'),('gold-korean.png','build/asian-gen2/live/gold-ko-nurse-healed.png','Korean Gold: actual nurse dialogue','A real healing interaction with the native Korean font.'),('emerald-portuguese.png','build/merge-qa/pt-BR-healing.png','Emerald in Brazilian Portuguese','Actual healing script, reached through the nurse interaction. Captured by the translation regression QA workflow.')]
for name,source,title,caption in shots:
 p=R/source;assert p.is_file(),p;shutil.copyfile(p,P/name)
intro={
 'de':('Pokémon-Sprachmod für Gen1Recomp','Deutsch, Englisch, brasilianisches Portugiesisch sowie unterstützte französische, italienische, spanische, japanische und koreanische Spielprofile. Sprach-ROM einmal importieren und verarbeiten; später über ASCENDANT → UNI-LANGUAGE wechseln.'),
 'pt-BR':('Mod de tradução Pokémon para Gen1Recomp','Jogue as onze edições compatíveis em português brasileiro. Importe sua ROM de idioma e use ASCENDANT → UNI-LANGUAGE para trocar de idioma no mesmo local. O idioma do menu é independente do idioma do jogo.'),
 'es':('Mod de idiomas Pokémon para Gen1Recomp','Importa tu ROM de idioma y cambia desde ASCENDANT → UNI-LANGUAGE. Consulta la tabla: los idiomas de juego disponibles dependen de la edición. El idioma del menú se elige por separado.'),
 'fr':('Mod de traduction Pokémon pour Gen1Recomp','Importez votre ROM de langue puis changez la langue dans ASCENDANT → UNI-LANGUAGE. Consultez le tableau pour les éditions prises en charge. La langue du menu est indépendante de celle du jeu.'),
 'it':('Mod di traduzione Pokémon per Gen1Recomp','Importa la tua ROM della lingua e cambia da ASCENDANT → UNI-LANGUAGE. Le lingue del gioco disponibili dipendono dall’edizione; la lingua del menu si sceglie separatamente.'),
 'ja':('Gen1Recomp用ポケモン言語MOD','Uni-Language Ascendantは、対応する言語ROMを取り込むためのMODです。日本語のクリスタルに対応しています。ゲームと言語メニューの対応範囲は異なります。必要なROMの版とSHA-1を確認してください。'),
 'ko':('Gen1Recomp 포켓몬 언어 모드','Uni-Language Ascendant는 한국어 금·은 게임 언어를 지원합니다. 언어 ROM을 가져온 뒤 ASCENDANT → UNI-LANGUAGE에서 전환합니다. 메뉴 언어와 게임 언어의 지원 범위는 다릅니다.'),
 'zh-Hans':('Gen1Recomp 宝可梦语言模组','支持十种菜单语言，游戏语言取决于具体版本。导入匹配的语言ROM后，通过 ASCENDANT → UNI-LANGUAGE切换。简体中文目前仅用于模组菜单。'),
 'zh-Hant':('Gen1Recomp 寶可夢語言模組','支援十種選單語言，遊戲語言依版本而異。匯入符合的語言ROM後，透過 ASCENDANT → UNI-LANGUAGE切換。繁體中文目前僅用於模組選單。'),
}
bodyrows=[]
for row in rows:
 supported={'en',*(s['language'] for s in row['sources'])}
 bodyrows.append('<tr><th>'+games[row['game']]+'</th>'+''.join('<td class="yes" aria-label="supported">✓</td>' if lang in supported else '<td class="no" aria-label="not available">—</td>' for lang in names)+'</tr>')
figures=''.join(f'<figure><a href="screenshots/{name}"><img loading="lazy" src="screenshots/{name}" alt="{html.escape(title)}"></a><figcaption><b>{html.escape(title)}</b><br>{html.escape(caption)}</figcaption></figure>'for name,_,title,caption in shots)
localized=''.join(f'<article lang="{lang}" id="{lang}"><h3>{html.escape(title)}</h3><p>{html.escape(text)}</p></article>'for lang,(title,text)in intro.items())
faq=[('Which games are supported?','Pokémon Red, Blue, Yellow, Gold, Silver, Crystal, FireRed, LeafGreen, Ruby, Sapphire and Emerald, when supported by the underlying recompiler. Check the language matrix for each edition.'),('Which ROM do I need?','Use the supported English US base game and the exact language ROM listed in the ROM checklist. Version, revision and SHA-1 must match. The ZIP contains mod code and recipes; users supply their own ROM inputs.'),('Does the European Emerald ROM contain all languages?','No. Supported Emerald language editions are separate ROM inputs. USA/Europe identifies a region and does not supply a multilingual language selector.'),('How does live language switching work?','At a settled overworld location, open ASCENDANT → UNI-LANGUAGE. The mod keeps unsaved progress in memory, reloads the current game session in the same application, and resumes at the current location. A first-time compilation can take longer than switching a cached language.'),('Can I switch during dialogue, battle or an online session?','Finish the active dialogue, battle, movement or transition first. Switching is intended for settled offline overworld play. The menu refuses unsafe states.'),('Can I use Kanto Ascendant or Voxel Ascendant?','The language entry uses the shared Ascendant menu descriptor. KASC can collect it into its hub; a fallback hub combines VASC and language entries when KASC is absent. Compatibility results for tested versions are published with the release. Arbitrary mod combinations are not universally certified.'),('Are all ten menu languages also available in every game?','No. English, German, French, Italian, Spanish, Japanese, Korean, Simplified Chinese, Traditional Chinese and Brazilian Portuguese are menu options. Actual game profiles are listed in the matrix.'),('What happens when I update or uninstall?','Updates preserve the imported ROMs and mod profile. Uninstalling deletes the mod profile; reinstalling starts a new profile. A language switch does not overwrite the normal game save.')]
faqhtml=''.join('<details><summary>'+html.escape(q)+'</summary><p>'+html.escape(a)+'</p></details>'for q,a in faq)
schema={'@context':'https://schema.org','@type':'SoftwareApplication','name':'Uni-Language Ascendant','applicationCategory':'GameApplication','operatingSystem':'Platforms supported by Gen1Recomp; release QA on macOS','url':URL,'downloadUrl':RELEASE,'codeRepository':REPO,'license':REPO+'/blob/main/LICENSE.MD','description':'Pokémon language and translation mod for Gen1Recomp with ROM import, cached compilation, in-game language switching and ten menu languages.'}
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gen1Recomp Pokémon Language Mod — Uni-Language Ascendant</title><meta name="description" content="Pokémon language mod for Gen1Recomp: German, Brazilian Portuguese, supported European languages, Japanese Crystal and Korean Gold/Silver. ROM import, language switching and screenshots."><link rel="canonical" href="{URL}"><meta property="og:type" content="website"><meta property="og:title" content="Uni-Language Ascendant · Pokémon languages for Gen1Recomp"><meta property="og:description" content="Import once. Choose your game and menu languages. See supported editions and real gameplay screenshots."><meta property="og:url" content="{URL}"><meta property="og:image" content="{URL}screenshots/language-menu.png"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script><style>
:root{{color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:#08131e;color:#edf4ee;font:17px/1.65 system-ui,sans-serif}}main{{max-width:1180px;margin:auto;padding:36px 24px 80px}}header{{border-top:8px solid #ed3945;padding:40px 0 24px}}.eyebrow{{color:#7eddd5;font-weight:700;letter-spacing:.12em}}h1{{font-size:clamp(2.1rem,6vw,4.4rem);line-height:1.07;max-width:900px;margin:.3em 0}}h2{{font-size:1.9rem;margin-top:2.3em}}h3{{line-height:1.3}}a{{color:#82e2d7}}.lede{{max-width:850px;color:#c1d0d5;font-size:1.18rem}}.buttons{{display:flex;flex-wrap:wrap;gap:12px;margin:28px 0}}.button{{display:inline-block;padding:12px 20px;border-radius:10px;text-decoration:none;border:1px solid #33515e;font-weight:700}}.primary{{background:#e93645;color:white;border-color:#e93645}}nav{{display:flex;flex-wrap:wrap;gap:12px}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:22px}}.shots{{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){{.shots{{grid-template-columns:1fr}}}}figure{{margin:0;background:#142735;border:1px solid #284453;border-radius:15px;overflow:hidden}}img{{display:block;width:100%;height:auto;image-rendering:pixelated}}figcaption{{padding:20px;color:#bbced4;font-size:.93rem}}figcaption b{{color:#f1f4e9}}aside{{padding:22px;border-left:5px solid #f9ce5b;background:#142735;border-radius:8px}}.table{{overflow:auto}}table{{border-collapse:collapse;width:100%;min-width:720px}}th,td{{padding:12px;border-bottom:1px solid #29404f;text-align:center}}th:first-child{{text-align:left}}.yes{{color:#85dfb6;font-weight:700}}.no{{color:#647681}}article{{padding:18px;background:#10232f;border-radius:12px}}article h3{{margin-top:0}}details{{border-bottom:1px solid #29404f;padding:17px 0}}summary{{cursor:pointer;font-weight:650}}footer{{margin-top:60px;padding-top:24px;border-top:1px solid #29404f;color:#afc3cb;font-size:.88rem}}code{{overflow-wrap:anywhere}}li{{margin:.5em 0}}@media(prefers-reduced-motion:no-preference){{html{{scroll-behavior:smooth}}}}</style></head><body><main>
<header><div class="eyebrow">POKÉMON · GEN1RECOMP · LANGUAGE MOD</div><h1>Uni-Language<br>Ascendant</h1><p class="lede">Play the supported Pokémon Gen 1–3 editions in your language. Import a matching language ROM once, compile it locally, and choose game and menu languages separately.</p><div class="buttons"><a class="button primary" href="{RELEASE}">Download the latest release</a><a class="button" href="{REPO}">GitHub source &amp; QA</a><a class="button" href="#install">Install guide</a></div><nav><a href="#languages">Language matrix</a><a href="#screenshots">Gameplay screenshots</a><a href="#live">In-game switching</a><a href="#faq">FAQ</a><a href="#international">Other languages</a></nav></header>
<aside><b>41 localized profiles · 11 editions · 10 menu languages.</b> Each game language needs its own supported input. This is a standalone mod for the Gen 1 Recompilation Project. The recompiler and the source ROMs are separate requirements.</aside>
<section id="screenshots"><h2>Real gameplay, real language profiles</h2><p>The screenshots below come from actual game interactions and the running mod menu. Some captures use prepared test saves. Tests do not supply invented dialogue as translation evidence.</p><div class="grid shots">{figures}</div></section>
<section id="languages"><h2>Which Pokémon game languages are supported?</h2><p>✓ means a supported profile exists. A grey dash means that edition’s game-language profile is still unavailable. Menu languages are independent.</p><div class="table"><table><thead><tr><th>Edition</th>{''.join('<th>'+html.escape(x)+'</th>'for x in names.values())}</tr></thead><tbody>{''.join(bodyrows)}</tbody></table></div><p>Menus: English, Deutsch, français, italiano, español, 日本語, 한국어, 简体中文, 繁體中文 and português brasileiro. Chinese currently applies to the mod menu.</p></section>
<section id="install"><h2>Install a Gen1Recomp language mod</h2><ol><li>Import the exact supported English US base game in Gen1Recomp.</li><li>Download the mod ZIP from <a href="{RELEASE}">GitHub Releases</a>, install it through the mod manager and enable Uni-Language Ascendant.</li><li>Import your matching language ROM through the launcher’s mod imports or the desktop file picker in the in-game language menu. On platforms without a host file picker, use the launcher’s Imports panel. Compare the complete file’s SHA-1 with the <a href="roms.html">ROM version checklist</a>.</li><li>Choose the menu language and the available game language. The Ascendant intro runs once per mod profile.</li></ol><p>Sapphire PT-BR uses the exact Ruby PT-BR import with separate Sapphire recipes and authored compatibility text. FRLG PT-BR patch-source revisions differ from the runtime US base: follow the checksum list.</p></section>
<section id="live"><h2>ASCENDANT → UNI-LANGUAGE</h2><p>Choose a game language, change the menu language immediately, add a language ROM or check the required revision and SHA-1. Unavailable game languages remain visible and disabled.</p><p>A game-language change uses an in-process session handoff. At a settled overworld location, the current progress is kept in memory, enabled mods reload with the new language, and play resumes at the same location. The application stays open during the loading pause. Large Ascendant combinations take noticeably longer than the language mod alone. The first compilation takes longer than using a cached language.</p><p>Dialogue, battle, movement, transitions and online rooms must finish first. The normal save file is not overwritten by the switch. A failed switch attempts to restore the previous language; an interrupted handoff retains a separate recovery record.</p><p>KASC and VASC share an Ascendant menu descriptor; the fallback hub can collect their entries alongside Languages. Origami Gen3 receives a language entry in its Ascendant menu. See the release QA for the exact tested combinations.</p></section>
<section id="faq"><h2>Questions about ROMs, translations and compatibility</h2>{faqhtml}</section>
<section id="international"><h2>Uni-Language Ascendant in your language</h2><div class="grid">{localized}</div></section>
<footer><p>Standalone community mod for <a href="https://github.com/bryanthaboi/gen1recomp">the Pokémon Gen 1 Recompilation Project</a> by BOIS CLUB GAMES, LLC. Mod code follows the existing GPLv3 license and attribution. Pokémon names, cartridge text and graphics belong to their respective rights holders.</p><p>Native language-ROM text and authored US-compatibility/UI translations are identified separately in the QA reports. Scoped automated gameplay checks are documented; full-story playthroughs, native-speaker certification and universal compatibility with arbitrary mods are not claimed.</p><a href="{REPO}/blob/main/mod/ASIAN-QA.json">Asian profile QA</a> · <a href="{REPO}/blob/main/mod/MERGE-QA.json">Integration QA</a> · <a href="{REPO}/blob/main/LICENSE.MD">License</a></footer>
</main></body></html>'''
(D/'index.html').write_text(page)
romsections=[]
for row in rows:
 entries=[dict(row['base'],language='en')]+row['sources']
 trs=''.join('<tr><td>'+html.escape(names[e['language']])+'</td><td>'+html.escape(e['name'])+'</td><td>'+html.escape(e['version'])+'</td><td><code>'+e['sha1']+'</code></td></tr>'for e in entries)
 romsections.append('<section><h2>'+games[row['game']]+'</h2><div class="table"><table><thead><tr><th>Language</th><th>Input ROM</th><th>Revision / source</th><th>Full-file SHA-1</th></tr></thead><tbody>'+trs+'</tbody></table></div></section>')
(D/'roms.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Required Pokémon ROM versions and SHA-1 — Uni-Language Ascendant</title><meta name="description" content="Exact English base and language ROM revisions and SHA-1 hashes for all 41 supported Uni-Language Ascendant profiles."><link rel="canonical" href="'+URL+'roms.html"><style>body{font:16px/1.6 system-ui,sans-serif;background:#08131e;color:#edf4ee;margin:28px}main{max-width:1200px;margin:auto}a{color:#82e2d7}.table{overflow:auto}table{border-collapse:collapse;width:100%}td,th{padding:12px;border-bottom:1px solid #33515e;text-align:left}code{white-space:nowrap}h2{margin-top:2em}</style></head><body><main><a href="index.html">← Guide &amp; screenshots</a><h1>Required ROM revisions &amp; SHA-1</h1><p>Gen1Recomp requires the matching English US base. Each language profile additionally requires the exact source below. The checksum identifies the complete, uncompressed ROM file; a matching file name is insufficient. The mod checks both the size and MD5 import receipt, plus SHA-1 in the in-game importer.</p><p>PT-BR inputs are fan translations, not official releases. See <a href="'+REPO+'/blob/main/tools/ptbr_sources.json">patch projects and source revisions</a>. Sapphire PT-BR uses the listed Ruby translation source, with a separate Sapphire profile. This project does not distribute source ROMs.</p>'+''.join(romsections)+'</main></body></html>')
(D/'.nojekyll').write_text('')
(D/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+URL+'sitemap.xml\n')
(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>'+URL+'</loc></url><url><loc>'+URL+'roms.html</loc></url></urlset>\n')
I=D/'i18n';I.mkdir(exist_ok=True)
for lang,(title,text)in intro.items():
 (I/f'README.{lang}.md').write_text('# '+title+'\n\n**Uni-Language Ascendant** · Pokémon Red / Blue / Yellow / Gold / Silver / Crystal / FireRed / LeafGreen / Ruby / Sapphire / Emerald.\n\n'+text+'\n\n[Download / GitHub Releases]('+RELEASE+') · [English guide & screenshots]('+URL+') · [Supported profiles](https://roxas2712.github.io/uni-language-ascendant/#languages)\n\n10 menu languages; 41 localized game profiles. Consult the edition matrix and exact ROM SHA-1 requirements.\n')
print('PROJECT_SITE_OK',len(rows),'editions;',len(shots),'real screenshots;',len(intro),'localized introductions')
